import {eventDates,validDate,costTotal,travelCalc,round} from './calc.mjs';
const $=s=>document.querySelector(s), esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const money=n=>Number(n).toLocaleString('uk-UA',{minimumFractionDigits:2,maximumFractionDigits:2}),num=n=>Number(n).toLocaleString('uk-UA',{maximumFractionDigits:2});
const today=()=>new Intl.DateTimeFormat('en-CA',{timeZone:'Europe/Kyiv',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date());
const date=s=>s?new Date(s+'T12:00:00').toLocaleDateString('uk-UA'):'__________';
const longDate=s=>{if(!s)return '________________';const d=new Date(s+'T12:00:00');return `«${String(d.getDate()).padStart(2,'0')}» ${['січня','лютого','березня','квітня','травня','червня','липня','серпня','вересня','жовтня','листопада','грудня'][d.getMonth()]} ${d.getFullYear()} року`};
const defaults=()=>({version:1,event:{venue:'',date:today(),receiptDate:'',number:'',city:'Київ',person:'',products:['Дона'],items:['Чай','Кава','Цукерки','Печиво'].map(name=>({name,qty:1,price:0}))},profile:{company:'«МЕДА Фармасьютікалз Світселенд ГмБх»',head:'В. С. Піонт',budgetHead:'Піонт В.С.',position:'Голова представництва'},products:['Дона','Целебрекс','Лірика','Алдара','Елідел','Зіклара'],travel:{liters:0,rate:10,startFuel:20,endTarget:20,adjustmentKm:0,refill:0,odometer:12675.7,basis:'seat · вересень 2026 · D21/F21/G21',driver:'',car:'SEAT',plate:'',from:today(),to:today(),rows:[{date:today(),route:'',km:0}]},archive:[]});
const standalone=matchMedia('(display-mode: standalone)').matches||navigator.standalone===true;if(standalone)document.documentElement.classList.add('standalone');
let state=defaults(),storageOK=true,view='event',docType='order',deferredInstall,contactKind='clinics';
try{const saved=JSON.parse(localStorage.getItem(storageKey)||(session.user.role==='admin'?localStorage.getItem('zvit-v1'):null));if(saved&&saved.version===1&&saved.event&&saved.travel&&Array.isArray(saved.archive))state={...state,...saved,profile:{...state.profile,...saved.profile}}}catch{storageOK=false}
migrateDirectories(state);
if(Array.isArray(state.products)&&!state.products.includes('Зіклара'))state.products.push('Зіклара');state.event.city='Київ';state.event.number='';
if(!state.preset||typeof state.preset!=='object')state.preset={city:'',person:'',representativeId:'',products:[],items:[]};
state.travel.endTarget ??= state.travel.startFuel;state.travel.adjustmentKm ??= 0;
const parentOf={eventEdit:'event',eventSettings:'event',travel:'fuel',carSettings:'fuel',contacts:'profile',signer:'profile',accounts:'profile',password:'profile'};
const rootOf=v=>parentOf[v]?rootOf(parentOf[v]):v;
function save(){try{localStorage.setItem(storageKey,JSON.stringify(state));storageOK=true}catch{storageOK=false}}
function toast(msg){$('#toast').textContent=msg;$('#toast').classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').classList.remove('show'),4000)}

/* ---------- Іконки ---------- */
const P={sliders:'M4 6h9M17 6h3M4 12h3M11 12h9M4 18h11M19 18h1M15 4v4M9 10v4M17 16v4',home:'M3 10.5 12 3l9 7.5V20a1 1 0 0 1-1 1h-5v-6H9v6H4a1 1 0 0 1-1-1z',doc:'M7 3h7l5 5v12a1 1 0 0 1-1 1H7a1 1 0 0 1-1-1V4a1 1 0 0 1 1-1zM14 3v5h5M9 13h6M9 17h6',car:'M5 17h14M6 17v2M18 17v2M4 13l2-6h12l2 6v4H4zM7.5 14.5h.01M16.5 14.5h.01',list:'M8 6h12M8 12h12M8 18h12M4 6h.01M4 12h.01M4 18h.01',user:'M12 12a4 4 0 1 0 0-8 4 4 0 0 0 0 8zM4 21a8 8 0 0 1 16 0',users:'M9 11a4 4 0 1 0 0-8 4 4 0 0 0 0 8zM2 21a7 7 0 0 1 14 0M16 3.5a4 4 0 0 1 0 7M18 14a6 6 0 0 1 4 7',right:'m9 6 6 6-6 6',left:'m15 5-7 7 7 7',plus:'M12 5v14M5 12h14',print:'M7 9V3h10v6M7 17H4v-7h16v7h-3M7 14h10v7H7z',eye:'M2 12s3.5-7 10-7 10 7 10 7-3.5 7-10 7S2 12 2 12zM12 15a3 3 0 1 0 0-6 3 3 0 0 0 0 6z',save:'M6 3h12v18l-6-4-6 4z',download:'M12 4v11M7 10l5 5 5-5M5 20h14',upload:'M12 20V9M7 14l5-5 5 5M5 4h14',phone:'M8 2h8a1 1 0 0 1 1 1v18a1 1 0 0 1-1 1H8a1 1 0 0 1-1-1V3a1 1 0 0 1 1-1zM11 18h2',x:'M6 6l12 12M18 6 6 18',building:'M4 21V5a1 1 0 0 1 1-1h9a1 1 0 0 1 1 1v16M15 9h4a1 1 0 0 1 1 1v11M3 21h18M8 8h3M8 12h3M8 16h3',pen:'M4 20h4L19 9l-4-4L4 16zM13 7l4 4',search:'M11 18a7 7 0 1 0 0-14 7 7 0 0 0 0 14zM20 20l-4-4',next:'M5 12h14M13 6l6 6-6 6',check:'M5 12.5l4.5 4.5L19 7',chart:'M4 20V10M10 20V4M16 20v-7M22 20H2',fuel:'M4 21V5a2 2 0 0 1 2-2h6a2 2 0 0 1 2 2v16M3 21h12M14 10h2a2 2 0 0 1 2 2v4a1.5 1.5 0 0 0 3 0V8l-3-3M7 8h4',back:'M3 12a9 9 0 1 0 3-6.7M3 4v5h5',key:'M15 7a4 4 0 1 0-3.5 5.9L10 14.5V17H7.5v2.5H5V21H2v-3l7.1-7.1A4 4 0 0 0 15 7zM16 6h.01',logout:'M15 4h3a2 2 0 0 1 2 2v12a2 2 0 0 1-2 2h-3M10 17l5-5-5-5M15 12H3'};
const icon=(n,c='')=>`<svg class="ic ${c}" viewBox="0 0 24 24" aria-hidden="true"><path d="${P[n]}"/></svg>`;

/* ---------- Будівельні блоки ---------- */
function field(label,key,value,type='text',extra=''){return `<label class="field"><span>${label}</span><input type="${type}" data-key="${key}" value="${esc(value)}" ${extra}></label>`}
function pickField(label,key,value,kind,target,extra=''){const clinic=kind==='clinics',rows=state[kind];return `<div class="field"><label for="f-${key}">${label}</label><div class="input-pick"><input id="f-${key}" type="text" data-key="${key}" value="${esc(value)}" ${extra}><span class="pick-btn" aria-hidden="true">${icon(clinic?'building':'user')}</span><select class="pick-select" data-contact-picker="${kind}" data-target="${target}" aria-label="Вибрати з довідника"><option value="">${rows.length?(clinic?'Вибрати клініку':'Вибрати з представників'):'Довідник порожній'}</option>${rows.map(r=>`<option value="${esc(r.id)}">${esc(r.name)}${clinic&&r.city?' · '+esc(r.city):''}</option>`).join('')}${target==='event'?`<option value="__save">＋ Зберегти введене в довідник</option>`:''}<option value="__open">＋ Новий запис у довіднику</option></select></div></div>`}
const btn=(text,action,cls='button')=>`<button class="${cls}" data-action="${action}">${text}</button>`;
const group=(title,body,cls='')=>`<section class="group ${cls}">${title?`<h2 class="group-title">${title}</h2>`:''}<div class="card">${body}</div></section>`;
const row=(ic,title,sub,action,extra='')=>`<button class="row" data-action="${action}" ${extra}><span class="avatar">${icon(ic)}</span><span class="row-main"><b>${title}</b>${sub?`<small>${sub}</small>`:''}</span>${icon('right','chev')}</button>`;
const quick=(...a)=>`<div class="quick">${a.map(([ic,label,action])=>`<button data-action="${action}"><span class="q-icon">${icon(ic)}</span><span>${label}</span></button>`).join('')}</div>`;
const plural=(n,one,few,many)=>{const m10=n%10,m100=n%100;return `${n} ${m10===1&&m100!==11?one:m10>=2&&m10<=4&&(m100<12||m100>14)?few:many}`};
const monthName=s=>{if(!s)return '';const d=new Date(s.slice(0,7)+'-15T12:00:00');return d.toLocaleDateString('uk-UA',{month:'long',year:'numeric'})};

/* ---------- Головна ---------- */

/* ---------- Круглий стіл ---------- */
function eventView(){const list=state.archive.filter(r=>r.type==='event').sort((a,b)=>(b.date||'').localeCompare(a.date||''));return {body:`<header class="large-title"><div><small>${plural(list.length,'круглий стіл','круглі столи','круглих столів')}</small><h1>Круглі столи</h1></div><button class="round" data-action="event-settings" aria-label="Налаштування події">${icon('sliders')}</button></header>
 ${list.length?`<section class="group"><h2 class="group-title">Усі</h2><div class="card">${list.map(r=>`<div class="row-wrap"><button class="row" data-action="event-open" data-id="${esc(r.id)}"><span class="avatar event">${icon('doc')}</span><span class="row-main"><b>${esc(r.title||'Без назви')}</b><small>${[date(r.date),...(r.data.products||[])].map(esc).join(' · ')}</small></span><span class="row-amount">${money(costTotal(r.data.items||[]))} ₴</span></button><button class="icon-btn" data-delete-archive="${r.id}" aria-label="Видалити ${esc(r.title)}">${icon('x')}</button></div>`).join('')}</div></section>`:`<section class="group"><div class="card empty">${icon('doc','big')}<b>Ще немає круглих столів</b><p>Натисніть «Створити новий» внизу.</p></div></section>`}`,bar:`<button class="button pill" data-action="event-create">${icon('plus')}Створити новий</button>`}}
function eventEditView(){const e=state.event;e.city=CITY;const step=(n,t)=>`<span class="step-n">${n}</span>${t}`;return {title:e.archiveId?'Круглий стіл':'Новий круглий стіл',left:`<button class="round ghost" data-action="event-close" aria-label="Закрити">${icon('x')}</button>`,right:`<button class="text-btn" data-action="event-save">Зберегти</button>`,
 body:` <section class="doc-pair"><button class="doc-card" data-doc="order"><span class="doc-ic">${icon('doc')}</span><b>Наказ</b><small id="order-state"></small></button><button class="doc-card" data-doc="budget"><span class="doc-ic">${icon('list')}</span><b>Кошторис</b><small id="budget-state"></small></button></section>
 ${group(step(1,'Клініка'),`${pickField('Назва закладу','event.venue',e.venue,'clinics','event','placeholder="Виберіть або введіть клініку" maxlength="180"')}`)}
 ${group(step(2,'Дати'),`<div class="field-grid">${field('Круглий стіл','event.date',e.date,'date','required')}${field('Дата чеку','event.receiptDate',e.receiptDate||'','date','required')}</div><p class="hint" id="order-date"></p>`)}
 ${group(step(3,'Відповідальна особа'),`${pickField('ПІБ у давальному відмінку','event.person',e.person,'representatives','event','placeholder="Кузьмінській Уляні Іванівні" maxlength="180"')}`)}
 ${group(step(4,'Препарати'),`<div class="chips">${state.products.map(p=>`<button class="chip ${e.products.includes(p)?'checked':''}" data-product="${esc(p)}" aria-pressed="${e.products.includes(p)}">${e.products.includes(p)?icon('check'):''}${esc(p)}</button>`).join('')}</div><div class="inline-add"><input id="new-product" placeholder="Інший препарат" aria-label="Назва нового препарату" maxlength="80"><button class="round soft" data-action="add-product" aria-label="Додати препарат">${icon('plus')}</button></div>`)}
 ${group(step(5,'Витрати'),`<p class="hint" style="margin:-6px 2px 12px">Суму можна залишити порожньою, якщо її ще немає.</p><div class="budget-rows">${e.items.map((r,i)=>`<div class="budget-row"><input class="b-name" aria-label="Позиція ${i+1}" placeholder="Назва позиції" data-item="${i}" data-prop="name" value="${esc(r.name)}" maxlength="120"><button class="icon-btn" data-remove-item="${i}" aria-label="Видалити позицію ${i+1}">${icon('x')}</button><label class="mini"><span>К-сть</span><input data-item="${i}" data-prop="qty" type="number" inputmode="decimal" min="0.01" step="0.01" value="${r.qty}" aria-label="Кількість ${i+1}"></label><label class="mini"><span>Сума за од., ₴</span><input data-item="${i}" data-prop="price" type="number" inputmode="decimal" min="0" step="0.01" value="${Number(r.price)?r.price:''}" placeholder="—" aria-label="Ціна ${i+1}"></label><b class="b-total" data-line-total="${i}"></b></div>`).join('')}</div><button class="add-row" data-action="add-item">${icon('plus')}Додати позицію</button>`)}
`}}

/* ---------- Подорожній лист ---------- */
let fuelRows=[],fuelLoaded=false;
function prepareMonthly(){const t=state.travel;if(t.fuelMode!=='filled'){t.refill=travelCalc(t).refill??0;t.fuelMode='filled';}const bounds=monthBounds(t.from?.slice(0,7));if(bounds){Object.assign(t,bounds);t.rows.forEach(row=>{if(row.date<t.from||row.date>t.to)row.date=t.from;});}Object.assign(t,filledTravel(t));}
function previousLine(){const row=prevRecord(state.travel);if(!row)return '';const r=fuelMetrics(row),t=state.travel,same=Math.abs(Number(t.startFuel)-r.endFuel)<0.01&&Math.abs(Number(t.odometer)-r.endOdo)<0.01;return same?`<p class="hint">Початкові дані взято з ${esc(monthName(row.from).replace(/ р\.$/,''))}.</p>`:`<p class="hint">У ${esc(monthName(row.from).replace(/ р\.$/,''))} на приїзді було ${num(r.endFuel)} л і ${num(r.endOdo)} км, а тут введено інше.</p><div class="card-foot">${btn(icon('back')+'Взяти з попереднього місяця','fuel-previous','link')}</div>`}
function tankMax(){const t=state.travel;return Math.max(1,Math.min(TANK,Math.floor((Number(t.startFuel||0)+Number(t.refill||0))*2)/2))}
const prevRecord=t=>previousMonthRecord(fuelRows,{...t,plate:''});const hasPrevious=()=>!!prevRecord(state.travel);
function setMonth(month){const bounds=monthBounds(month);if(!bounds)return toast('Виберіть коректний місяць.');Object.assign(state.travel,bounds);state.travel.rows.forEach(row=>row.date=bounds.from);state.travel.refill=0;state.travel.realKm='';state.travel.adjustmentKm=0;delete state.travel.autoBasisMonth;return previousFuel().then(()=>{save();render()})}
const TANK=40,CITY='Київ',ROUTES=[{route:'Львів – Тернопіль – Львів',km:260},{route:'Львів – Хмельницький – Львів',km:480}];
const shiftMonth=(from,d)=>{const x=new Date(from.slice(0,7)+'-15T12:00:00Z');x.setUTCMonth(x.getUTCMonth()+d);return x.toISOString().slice(0,7)};
function travelView(){prepareMonthly();if(!fuelLoaded)loadFuel().then(ok=>{if(ok&&view==='travel'){const row=prevRecord(state.travel);if(row&&state.travel.refill===0&&!state.travel.autoBasisMonth){const result=travelCalc(row);Object.assign(state.travel,{odometer:result.endOdo,startFuel:result.endFuel,endTarget:result.endFuel,rate:row.rate,autoBasisMonth:state.travel.from.slice(0,7),basis:'попередній місяць '+row.from.slice(0,7)});Object.assign(state.travel,filledTravel(state.travel));}render();}});
 const t=state.travel,prev=hasPrevious(),realOdo=t.realKm===''||t.realKm==null?'':round(Number(t.odometer)+Number(t.realKm));return {title:esc(monthName(t.from).replace(/ р\.$/,'').replace(/^./,c=>c.toUpperCase())),right:`<button class="round ghost" data-action="car-settings" aria-label="Налаштування авто">${icon('sliders')}</button>`,
 body:`<section class="hero fuel-hero"><div class="month-switch"><button class="round glass" data-action="month-prev" aria-label="Попередній місяць">${icon('left')}</button><b>${esc(monthName(t.from).replace(/ р\.$/,''))}</b><button class="round glass" data-action="month-next" aria-label="Наступний місяць">${icon('right')}</button></div><button class="car-line" data-action="car-settings">${icon('car')}${esc([t.car,t.plate].filter(Boolean).join(' · ')||'Авто не вказано')}</button><span class="hero-label">Пробіг за місяць</span><div class="hero-amount" id="km-total"></div><div class="hero-status" id="fuel-status"></div></section>
 <section class="journey"><div class="j-head"><span></span><span>Виїзд</span><span></span><span>Приїзд</span></div><div class="j-row"><span>${icon('fuel')}Бак</span><b id="j-fuel-start"></b><i>→</i><b id="j-fuel-end"></b></div><div class="j-row"><span>${icon('car')}Одометр</span><b id="j-odo-start"></b><i>→</i><b id="j-odo-end"></b></div></section>
 ${prev?'':`<section class="fuel-input start"><label>Стартові дані</label><p class="hint" style="margin:2px 0 10px">Звіту за попередній місяць немає. Вкажіть, з чим виїжджаєте на початку місяця.</p><div class="field-grid">${field('Одометр, км','travel.odometer',t.odometer,'number','min="0" step="0.1" inputmode="decimal"')}${field('У баку, л','travel.startFuel',t.startFuel,'number','min="0" max="40" step="0.5" inputmode="decimal"')}</div></section>`}
 <section class="fuel-input"><label for="refill-input">Заправлено за місяць</label><div class="amount-input"><input id="refill-input" type="number" inputmode="decimal" min="0" step="0.01" data-key="travel.refill" value="${esc(t.refill||'')}" style="width:${String(t.refill||'0').length+.6}ch" placeholder="0"><span>л</span></div></section>
 <section class="fuel-input tank"><div class="tank-head"><label for="tank-range">У баку по приїзді</label><b id="tank-value"></b></div><div class="tank-scale"><span>0</span><span>20</span><span>40 л</span></div><div class="tank-row"><button class="round soft" data-action="tank-minus" aria-label="Менше на 1 л">−</button><div class="tank-track"><i class="tank-zone"></i><input id="tank-range" type="range" min="0" max="${tankMax()}" step="0.5" data-key="travel.endTarget" value="${esc(t.endTarget)}"></div><button class="round soft" data-action="tank-plus" aria-label="Більше на 1 л">+</button></div><p class="hint center" id="tank-hint"></p><div class="card-foot center">${btn('Поставити по центру · 20 л','tank-center','link')}</div></section>
 <section class="fuel-input"><label for="real-odo">Одометр на приладі зараз <small>· необов’язково</small></label><div class="field-row"><input id="real-odo" type="number" inputmode="decimal" min="0" step="0.1" data-real-odo value="${realOdo}" placeholder="Щоб звірити з розрахунком"></div><div id="real-comparison"></div></section>
 ${group('Для бланка',`<div class="sheet" id="sheet"></div><div class="card-foot">${btn(icon('eye')+'Переглянути бланк','travel-preview','link')}</div>`)}
 <details class="group more"><summary>Поїздки · необов’язково</summary><div class="card"><div class="route-chips">${ROUTES.map((x,i)=>`<button class="chip" data-add-route="${i}">${icon('plus')}${esc(x.route.replace(/ – Львів$/,''))} · ≈${x.km} км</button>`).join('')}</div><div id="trip-rows">${tripRows()}</div><button class="add-row" data-action="add-trip">${icon('plus')}Інша поїздка</button>${t.rows.length>1?`<div class="card-foot">${btn('Розподілити порівну','split-trips','link')}</div>`:''}</div></details>
 ${prev?`<details class="group more"><summary>Початкові дані</summary><div class="card"><div class="field-grid">${field('У баку при виїзді, л','travel.startFuel',t.startFuel,'number','min="0" step="0.01" inputmode="decimal"')}${field('Одометр при виїзді, км','travel.odometer',t.odometer,'number','min="0" step="0.01" inputmode="decimal"')}${field('Додатковий пробіг, км','travel.adjustmentKm',t.adjustmentKm,'number','min="0" step="0.1" inputmode="decimal"')}</div>${previousLine()}</div></details>`:''}`,
 bar:`<div class="bar-2"><button class="button secondary" data-action="travel-preview">${icon('eye')}Перегляд</button><button class="button" data-action="save-month">${icon('save')}Зберегти місяць</button></div>`}}
function presetSummary(){const p=state.preset;return `<div class="stat-grid two"><div><span>Препарати</span><b>${p.products.length?p.products.map(esc).join(', '):'—'}</b></div><div><span>Витрати</span><b>${p.items.length?p.items.map(r=>esc(r.name)+(Number(r.price)?' · '+money(Number(r.qty)*Number(r.price))+' ₴':'')).join('<br>'):'—'}</b></div></div>`}
function eventSettingsView(){const p=state.preset;return {title:'Налаштування події',body:`<p class="hint" style="margin:0 2px 18px">Типові дані підставляються в нову подію, коли ви натискаєте «Очистити». Змінювати їх щоразу не потрібно.</p>
 ${group('Типові дані',`${pickField('Відповідальна особа, у давальному відмінку','preset.person',p.person,'representatives','preset','maxlength="180" placeholder="Кузьмінській Уляні Іванівні"')}`)}
 ${group('Препарати і витрати',`${presetSummary()}<p class="hint">Відмітьте препарати й позиції витрат на екрані події, потім натисніть кнопку нижче.</p>`)}
 <div class="stack">${btn(icon('save')+'Запам’ятати з поточної події','preset-from-event','button secondary')}${btn(icon('check')+'Заповнити поточну подію','preset-apply','button')}</div>`}}
function applyPreset(e){const p=state.preset;e.city=CITY;if(p.person){e.person=p.person;if(p.representativeId)e.representativeId=p.representativeId}if(p.products.length)e.products=[...p.products];if(p.items.length)e.items=structuredClone(p.items);return e}
function carSettingsView(){const t=state.travel;return {title:'Налаштування авто',body:`<p class="hint" style="margin:0 2px 18px">Ці дані не змінюються щомісяця й автоматично підставляються в подорожній лист.</p>
 ${group('Автомобіль',`<div class="field-grid">${field('Марка','travel.car',t.car,'text','maxlength="120"')}${field('Держномер','travel.plate',t.plate,'text','maxlength="30"')}</div>${field('Норма витрати, л/100 км','travel.rate',t.rate,'number','min="0.01" step="0.01" inputmode="decimal"')}`)}
 ${group('Водій',`${pickField('ПІБ водія','travel.driver',t.driver,'representatives','travel','maxlength="180"')}`)}
 ${group('Реквізити бланка',`<div class="field-grid">${field('Номер листа','travel.number',t.number||'','text','maxlength="30"')}${field('Режим роботи','travel.workMode',t.workMode||'','text','maxlength="80"')}${field('Марка пального','travel.fuelBrand',t.fuelBrand||'','text','maxlength="30"')}${field('Код марки','travel.fuelCode',t.fuelCode||'','text','maxlength="20"')}${field('Час виїзду','travel.departTime',t.departTime||'','time')}${field('Час повернення','travel.returnTime',t.returnTime||'','time')}${field('Годин у наряді','travel.hours',t.hours||'','number','min="0" step="0.1"')}${field('Колона','travel.column',t.column||'','text','maxlength="30"')}${field('Бригада','travel.brigade',t.brigade||'','text','maxlength="30"')}</div>${field('Особливі відмітки','travel.notes',t.notes||'','text','maxlength="300"')}`)}`}}
function tripRows(){const result=travelCalc(state.travel);return state.travel.rows.map((r,i)=>{const last=i===state.travel.rows.length-1;return `<div class="trip"><div class="trip-top"><b>Поїздка ${i+1}</b>${last?'<span class="tag">решта пробігу</span>':''}<button class="icon-btn" data-remove-trip="${i}" aria-label="Видалити поїздку ${i+1}" ${state.travel.rows.length===1?'disabled':''}>${icon('x')}</button></div><input aria-label="Маршрут поїздки ${i+1}" placeholder="Маршрут (необов’язково)" data-trip="${i}" data-prop="route" value="${esc(r.route)}" maxlength="200"><div class="field-grid"><label class="field"><span>Дата</span><input type="date" data-trip="${i}" data-prop="date" value="${esc(r.date)}"></label><label class="field"><span>Пробіг, км</span><div class="stepper">${last?'':`<button data-step-trip="${i}" data-step="-1" aria-label="Зменшити пробіг поїздки ${i+1}">−</button>`}<input type="number" min="0" step="0.01" inputmode="decimal" aria-label="Пробіг поїздки ${i+1}" data-trip="${i}" data-prop="km" value="${last?result.rows?.[i]?.km??0:r.km}" ${last?'readonly data-last-km':''}>${last?'':`<button data-step-trip="${i}" data-step="1" aria-label="Збільшити пробіг поїздки ${i+1}">+</button>`}</div></label></div></div>`}).join('')}

/* ---------- Аналітика пального ---------- */
const sameCar=(a,b)=>String(a||'').trim().toUpperCase()===String(b||'').trim().toUpperCase();
function fuelView(){if(!fuelLoaded&&!fuelView.loading){fuelView.loading=true;loadFuel().then(()=>{fuelView.loading=false;if(view==='fuel')render()})}
 const rows=fuelRows.filter(x=>sameCar(x.car,state.travel.car)).sort((a,b)=>b.from.localeCompare(a.from)),year=today().slice(0,4),years=[...new Set([year,...rows.map(t=>t.from.slice(0,4))])].sort().reverse();
 const t=state.travel,draftSaved=rows.some(x=>x.from===t.from),draft=!draftSaved&&Number(t.refill)>0;
 const item=t=>{const r=fuelMetrics(t);return `<button class="row" data-action="fuel-open" data-index="${fuelRows.indexOf(t)}"><span class="avatar travel">${icon('fuel')}</span><span class="row-main"><b>${esc(new Date(t.from.slice(0,7)+'-15T12:00:00').toLocaleDateString('uk-UA',{month:'long',year:'numeric'}).replace(/ р\.$/,'').replace(/^./,c=>c.toUpperCase()))}</b><small>${num(r.refill)} л · ${fraction(r.actualRate,t.liters)}</small></span><span class="row-amount">${num(r.total)} км</span>${icon('right','chev')}</button>`};
 const yearRows=rows.slice(0,12),km=yearRows.reduce((a,x)=>a+(fuelMetrics(x).total||0),0),lit=yearRows.reduce((a,x)=>a+Number(x.liters||0),0);
 return {body:`<header class="large-title"><div><small>${esc([t.car,t.plate].filter(Boolean).join(' · '))}</small><h1>Подорожній</h1></div><button class="round" data-action="car-settings-root" aria-label="Налаштування авто">${icon('sliders')}</button></header>
 <section class="hero"><span class="hero-label">Останні ${plural(yearRows.length,'місяць','місяці','місяців')}</span><div class="hero-amount">${num(round(km))} <small>км</small></div><div class="hero-stats"><div><span>Місяців</span><b>${rows.length}</b></div><div><span>Витрачено</span><b>${num(round(lit))} л</b></div><div><span>Норма</span><b>${num(t.rate)} л/100</b></div></div></section>
 ${draft?`<button class="tile wide" data-action="fuel-continue"><span class="tile-icon">${icon('pen')}</span><span class="tile-text"><b>Продовжити ${esc(monthName(t.from).replace(/ р\.$/,''))}</b><small>Чернетка ще не збережена</small></span>${icon('right','chev')}</button>`:''}
 ${!fuelLoaded?`<p class="hint center">Завантажуємо місяці…</p>`:rows.length?`<section class="group"><h2 class="group-title">Місяці</h2><div class="card">${rows.map(item).join('')}</div></section>`:`<section class="group"><div class="card empty">${icon('fuel','big')}<b>Ще немає збережених місяців</b><p>Натисніть «Новий місяць» внизу.</p></div></section>`}
 ${session.user.role==='admin'?`<details class="group more"><summary>Імпорт історії</summary><div class="card">${row('upload','Імпортувати історію','З Excel і зразка, без заміни наявних записів','fuel-import')}</div></details>`:''}`,
 bar:`<button class="button pill" data-action="fuel-new">${icon('plus')}Новий місяць</button>`}}

/* ---------- Звіти ---------- */
function archiveRow(r){return `<div class="row-wrap"><button class="row" data-action="open-${r.id}"><span class="avatar ${r.type}">${icon(r.type==='event'?'doc':'car')}</span><span class="row-main"><b>${esc(r.title)}</b><small>${r.type==='event'?'Наказ + кошторис':'Подорожній лист'} · ${date(r.date)}</small></span></button><button class="icon-btn" data-delete-archive="${r.id}" aria-label="Видалити звіт ${esc(r.title)}">${icon('x')}</button></div>`}
function archiveList(q){const rows=state.archive.filter(r=>r.title.toLowerCase().includes(q.toLowerCase()));return rows.length?`<div class="card">${rows.slice().reverse().map(archiveRow).join('')}</div>`:`<div class="card empty">${icon(q?'search':'list','big')}<b>${q?'Звітів не знайдено':'Тут будуть ваші звіти'}</b><p>Заповніть документ і натисніть «Зберегти».</p></div>`}
function archiveView(){return {body:`<header class="large-title"><div><small>${plural(state.archive.length,'звіт','звіти','звітів')}</small><h1>Звіти</h1></div></header><label class="search">${icon('search')}<input id="archive-search" type="search" placeholder="Заклад або водій" aria-label="Пошук звіту"></label><section class="group" id="archive-list">${archiveList('')}</section>`}}

/* ---------- Профіль ---------- */
function profileView(){const p=state.profile,u=session.user;return {body:`<header class="large-title"><div><small>${u.role==='admin'?'Адміністратор':'Представник'}</small><h1>Профіль</h1></div></header>
 <section class="group"><div class="card"><div class="account"><span class="avatar big-av">${esc((u.name||'?').trim().charAt(0).toUpperCase())}</span><span class="row-main"><b>${esc(u.name)}</b><small>${esc(u.username)}</small></span></div>${u.role==='admin'?row('users','Користувачі','Доступ для представників','accounts'):''}${row('key','Змінити пароль','Від 12 символів','open-password')}</div></section>
 ${group('Довідники',row('building','Клініки',plural(state.clinics.length,'запис','записи','записів'),'contacts-clinics')+row('user','Представники',plural(state.representatives.length,'запис','записи','записів'),'contacts-representatives'))}
 ${group('Документи',row('pen','Підписант',esc(p.head+' · '+p.position),'open-signer'))}
 ${group('Дані',row('download','Завантажити резервну копію','JSON-файл зі звітами й довідниками','backup')+row('upload','Відновити з копії','Замінить поточні дані','restore')+(standalone?'':row('phone','Встановити на телефон','Іконка на головному екрані','install')))}
 <section class="group"><div class="card">${`<button class="row danger" data-action="logout"><span class="avatar">${icon('logout')}</span><span class="row-main"><b>Вийти</b></span></button>`}</div></section>
 <p class="foot-note">${storageOK?'Звіти й довідники зберігаються в цьому браузері, місячні записи пального — на сервері. Робіть резервну копію перед зміною пристрою.':'Локальне збереження недоступне. Завантажте резервну копію, щоб не втратити дані.'}</p>`}}
function signerView(){return {title:'Підписант',body:group('',`${field('Організація','profile.company',state.profile.company,'text','maxlength="200"')}${field('Посада','profile.position',state.profile.position,'text','maxlength="120"')}${field('Підпис у наказі','profile.head',state.profile.head,'text','maxlength="100"')}${field('Підпис у кошторисі','profile.budgetHead',state.profile.budgetHead,'text','maxlength="100"')}`)+'<p class="foot-note">Зміни застосовуються до нових документів.</p>'}}
function passwordView(){return {title:'Зміна пароля',body:group('',`<label class="field"><span>Поточний пароль</span><input id="current-password" type="password" autocomplete="current-password" maxlength="256"></label><label class="field"><span>Новий пароль · від 12 символів</span><input id="new-password" type="password" autocomplete="new-password" minlength="12" maxlength="256"></label><label class="field"><span>Повторіть новий пароль</span><input id="repeat-password" type="password" autocomplete="new-password" maxlength="256"></label>`)+'<p class="foot-note">Після зміни пароля потрібно буде увійти знову.</p>',bar:`<button class="button pill" data-action="change-password">Змінити пароль</button>`}}

/* ---------- Користувачі (адміністратор) ---------- */
let accountRows=[];
function accountsView(){if(session.user.role!=='admin')return {title:'Користувачі',body:''};return {title:'Користувачі',right:`<button class="round ghost" data-action="accounts" aria-label="Оновити">${icon('back')}</button>`,body:`
 ${group('Новий представник',`<label class="field"><span>ПІБ</span><input id="account-name" maxlength="180" autocomplete="name"></label><label class="field"><span>Логін · латиниця, цифри, . _ @ -</span><input id="account-username" maxlength="80" autocomplete="off" autocapitalize="none" spellcheck="false"></label><label class="field"><span>Початковий пароль · від 12 символів</span><input id="account-password" type="password" minlength="12" maxlength="256" autocomplete="new-password"></label><p class="hint">Передайте пароль особисто. Представник змінить його в профілі.</p><div class="form-actions single">${btn('Створити обліковий запис','create-account')}</div>`)}
 ${group('Усі користувачі',accountRows.map(r=>`<div class="account-item"><div class="account"><span class="avatar">${icon('user')}</span><span class="row-main"><b>${esc(r.name)}</b><small>${esc(r.username)} · ${r.role==='admin'?'Адміністратор':'Представник'} · ${r.active?'активний':'призупинено'}</small></span>${r.id===session.user.id?'<span class="tag">Це ви</span>':''}</div>${r.id===session.user.id?'':`<div class="account-actions"><button class="chip" data-action="toggle-account" data-id="${esc(r.id)}">${r.active?'Призупинити':'Відновити доступ'}</button><details><summary class="chip">Скинути пароль</summary><div class="inline-add"><input type="password" id="reset-${esc(r.id)}" placeholder="Новий пароль, від 12 символів" autocomplete="new-password" minlength="12" maxlength="256"><button class="button small" data-action="reset-account-password" data-id="${esc(r.id)}">Зберегти</button></div></details></div>`}</div>`).join(''))}`}}
async function showAccounts(){try{const data=await api('/api/users');accountRows=data.users;if(view==='accounts')render();else go('accounts');}catch(e){toast(e.message);}}
async function createAccount(){const button=document.querySelector('[data-action="create-account"]');button.disabled=true;try{await api('/api/users',{name:$('#account-name').value.trim(),username:$('#account-username').value.trim(),password:$('#account-password').value});await showAccounts();toast('Обліковий запис представника створено.');}catch(e){toast(e.message);button.disabled=false;}}
async function editAccount(action,id){try{const body=action==='toggle-account'?{active:!accountRows.find(row=>row.id===id).active}:{password:document.getElementById('reset-'+id).value};await api('/api/users/'+id,body,'PATCH');await showAccounts();toast(action==='toggle-account'?'Доступ оновлено.':'Пароль змінено. Попередні сесії завершено.');}catch(e){toast(e.message);}}
async function changePassword(){const password=$('#new-password').value;if(password!==$('#repeat-password').value)return toast('Нові паролі не збігаються.');try{await api('/api/password',{currentPassword:$('#current-password').value,password});await logout();}catch(e){toast(e.message);}}

/* ---------- Довідники ---------- */
const emptyContact=kind=>Object.fromEntries(directoryFields[kind].map(key=>[key,'']));
const contactDrafts={clinics:emptyContact('clinics'),representatives:emptyContact('representatives')};
const contactForm={clinics:false,representatives:false};
const inDirectory=kind=>{const e=state.event,lc=x=>String(x||'').trim().toLocaleLowerCase('uk');return kind==='clinics'?state.clinics.some(r=>lc(r.name)===lc(e.venue)&&lc(r.city)===lc(e.city)):state.representatives.some(r=>lc(r.person)===lc(e.person))};
function contactPicker(kind,target='event'){
 const clinic=kind==='clinics', current=state[target], rows=state[kind];
 if(!rows.length)return `<div class="picker-empty-wrap"><button class="row picker-empty" data-action="contacts-${kind}"><span class="avatar">${icon(clinic?'building':'user')}</span><span class="row-main"><b>${clinic?'Довідник клінік порожній':'Довідник представників порожній'}</b><small>Додайте запис, щоб потім вибирати його тут</small></span>${icon('right')}</button></div>`;
 const selected=rows.find(r=>r.id===current[clinic?'clinicId':'representativeId']&&(clinic?r.name===current.venue&&r.city===current.city:target==='travel'?r.name===current.driver:r.person===current.person));
 return `<label class="field picker"><span>${target==='travel'?'Водій із представників':'Із довідника'}</span><select data-contact-picker="${kind}" data-target="${target}"><option value="">Ввести вручну</option>${rows.map(r=>`<option value="${esc(r.id)}" ${selected?.id===r.id?'selected':''}>${esc(r.name)}${clinic&&r.city?' · '+esc(r.city):''}</option>`).join('')}</select></label>`;
}
function contactsView(){
 const kind=contactKind,clinic=kind==='clinics',draft=contactDrafts[kind];
 const labels={name:clinic?'Назва клініки':'ПІБ представника',city:'Місто',address:'Адреса',contact:'Контактна особа',phone:'Телефон',person:'ПІБ у давальному відмінку'};
 const form=contactForm[kind]||draft.id?group(draft.id?'Редагування':'Новий запис',`${directoryFields[kind].map(key=>`<label class="field"><span>${labels[key]}</span><input data-directory="${kind}" data-contact-field="${key}" value="${esc(draft[key])}" maxlength="300" type="${key==='phone'?'tel':'text'}"></label>`).join('')}<div class="form-actions">${btn('Скасувати','cancel-'+kind,'button secondary')}${btn(draft.id?'Зберегти':'Додати','save-'+kind)}</div>`):'';
 return {title:'Довідники',body:`<div class="segmented"><button data-ckind="clinics" class="${clinic?'selected':''}">Клініки</button><button data-ckind="representatives" class="${clinic?'':'selected'}">Представники</button></div>
 ${form}
 <section class="group"><div class="card">${form?'':`<button class="add-row top" data-action="add-contact">${icon('plus')}Додати ${clinic?'клініку':'представника'}</button>`}${state[kind].map(r=>`<div class="row-wrap"><button class="row" data-edit-contact="${esc(r.id)}" data-contact-kind="${kind}"><span class="avatar">${icon(clinic?'building':'user')}</span><span class="row-main"><b>${esc(r.name)}</b><small>${[clinic?r.city:r.person,clinic?r.address:'',r.phone].filter(Boolean).map(esc).join(' · ')||'&nbsp;'}</small></span></button><button class="icon-btn" data-remove-contact="${esc(r.id)}" data-contact-kind="${kind}" aria-label="Видалити ${esc(r.name)}">${icon('x')}</button></div>`).join('')}${!state[kind].length&&!form?`<p class="hint pad">${clinic?'Назва й місто клініки підставляються в документи події.':'ПІБ підставляється у наказ і подорожній лист.'}</p>`:''}</div></section>`};
}
function saveContact(kind){
 const draft=contactDrafts[kind],row={id:draft.id||crypto.randomUUID(),...Object.fromEntries(directoryFields[kind].map(k=>[k,draft[k].trim()]))};
 if(!validDirectory([row],kind))return toast(kind==='clinics'?'Введіть назву клініки.':'Введіть ПІБ представника та ПІБ у давальному відмінку.');
 const index=state[kind].findIndex(r=>r.id===row.id);
 if(index<0&&state[kind].length>=500)return toast('У довіднику може бути до 500 записів.');
 if(index<0)state[kind].push(row);else state[kind][index]=row;
 contactDrafts[kind]=emptyContact(kind);contactForm[kind]=false;save();render();toast(storageOK?'Запис збережено.':'Не вдалося зберегти на пристрої. Завантажте резервну копію.');
}
function rememberContact(kind){
 const clinic=kind==='clinics',e=state.event,name=(clinic?e.venue:e.person).trim();
 if(!name)return toast(clinic?'Спочатку введіть назву клініки.':'Спочатку введіть відповідальну особу.');
 if(!clinic){
  const existing=state.representatives.find(r=>r.person.toLocaleLowerCase('uk')===name.toLocaleLowerCase('uk'));
  if(existing){applyContact(state,kind,existing.id);save();render();return toast('Представника вже збережено.');}
  contactDrafts.representatives={...emptyContact(kind),person:name};contactKind='representatives';contactForm.representatives=true;go('contacts');
  document.querySelector('[data-directory="representatives"]')?.focus();
  return toast('Додайте ПІБ у називному відмінку та збережіть запис.');
 }
 const row=state[kind].find(r=>r.name.toLocaleLowerCase('uk')===name.toLocaleLowerCase('uk')&&(!clinic||r.city.trim().toLocaleLowerCase('uk')===e.city.trim().toLocaleLowerCase('uk')));
 if(row){applyContact(state,kind,row.id);save();render();return toast('Такий запис уже збережено. Змінити його можна в довіднику.');}
 if(state[kind].length>=500)return toast('У довіднику може бути до 500 записів.');
 const record={...emptyContact(kind),id:crypto.randomUUID(),name,...(clinic?{city:e.city.trim()}:{person:name})};
 state[kind].push(record);applyContact(state,kind,record.id);save();render();toast(storageOK?'Дані збережено в довіднику.':'Не вдалося зберегти на пристрої. Завантажте резервну копію.');
}

/* ---------- Пальне на сервері ---------- */
async function loadFuel(){try{fuelRows=(await api('/api/fuel')).records;fuelLoaded=true;return true;}catch(e){toast(e.message);return false;}}
async function saveFuel(){prepareMonthly();if(!validFuel(state.travel))throw Error('Перевірте місяць, автомобіль, залиті літри, залишки та пробіг. Витрата має бути більшою за нуль.');await api('/api/fuel',state.travel);await loadFuel();}
async function previousFuel(){if(!await loadFuel())return;prepareMonthly();const t=state.travel,row=prevRecord(t);if(!row){render();return toast('Немає запису за попередній місяць. Початкові дані залишено для ручного введення.');}const r=travelCalc(row);Object.assign(t,{odometer:r.endOdo,startFuel:r.endFuel,endTarget:r.endFuel,rate:row.rate,autoBasisMonth:t.from.slice(0,7),basis:'попередній місяць '+row.from.slice(0,7)});Object.assign(t,filledTravel(t));save();render();}

async function newMonth(){await loadFuel();const t=state.travel,mine=fuelRows.filter(x=>sameCar(x.car,t.car)).sort((a,b)=>b.from.localeCompare(a.from)),last=mine[0];const month=last?shiftMonth(last.from,1):today().slice(0,7),bounds=monthBounds(month);const base={...bounds,liters:0,refill:0,realKm:'',fuelMode:'filled',adjustmentKm:0,rows:[{date:bounds.from,route:'',km:0}]};if(last){const r=travelCalc(last);Object.assign(t,base,{startFuel:r.endFuel,endTarget:r.endFuel,odometer:r.endOdo,rate:last.rate,autoBasisMonth:bounds.from.slice(0,7),basis:'попередній місяць '+last.from.slice(0,7)})}else Object.assign(t,base,{autoBasisMonth:bounds.from.slice(0,7)});save();docType='travel';go('travel');fuelLoaded=true;render()}
let finishing=false;
function upsertEvent(){const copy=structuredClone(state.event);if(!copy.archiveId)copy.archiveId=state.event.archiveId=crypto.randomUUID();const rec={id:copy.archiveId,type:'event',title:copy.venue,date:copy.date,data:copy,profile:structuredClone(state.profile)},i=state.archive.findIndex(r=>r.id===rec.id);if(i<0)state.archive.push(rec);else state.archive[i]=rec;save()}
function eventDone(){const errors=eventErrors(true);if(errors.length)return toast('Заповніть: '+errors.join(', ')+'.');upsertEvent();printDoc('order',true)}
/* ---------- Рендер ---------- */
const views={eventEdit:eventEditView,event:eventView,travel:travelView,fuel:fuelView,archive:archiveView,profile:profileView,contacts:contactsView,signer:signerView,password:passwordView,accounts:accountsView,carSettings:carSettingsView,eventSettings:eventSettingsView};
function render(){
 const v=views[view](),pushed=!!parentOf[view];
 document.body.dataset.view=view;document.body.classList.toggle('pushed',pushed);
 $('#appbar').innerHTML=pushed?`${v.left||`<button class="round ghost" data-action="back" aria-label="Назад">${icon('left')}</button>`}<b>${v.title}</b><span class="appbar-right">${v.right||''}</span>`:'';
 $('#content').innerHTML=v.body;
 $('#actionbar').innerHTML=v.bar||'';document.body.classList.toggle('has-bar',!!v.bar);
 const tab=rootOf(view);document.querySelectorAll('.tabbar [data-view]').forEach(el=>{el.classList.toggle('active',el.dataset.view===tab);el.setAttribute('aria-current',el.dataset.view===tab?'page':'false')});
 updateDerived();
}
function transition(dir,fn){if(!document.startViewTransition||matchMedia('(prefers-reduced-motion: reduce)').matches)return fn();document.documentElement.dataset.nav=dir;document.startViewTransition(fn)}
function go(next){if(next===view)return render();const pushed=!!parentOf[next];view=next;if(next==='travel'){docType='travel';fuelLoaded=false}else if(next==='event')docType='order';pushed?history.pushState({view:next,pushed:true},''):history.replaceState({view:next},'');transition(pushed?'forward':'tab',()=>{render();window.scrollTo(0,0)})}
function back(){if(history.state?.pushed)history.back();else{view=parentOf[view]||'event';history.replaceState({view},'');render()}}
window.addEventListener('popstate',e=>{if($('#preview-dialog').open)$('#preview-dialog').close();view=e.state?.view||'event';if(view==='travel')docType='travel';transition('back',render)});
function updateDerived(){
 if(view==='eventEdit'){const oe=eventErrors(false),be=eventErrors(true).filter(x=>!oe.includes(x)),os=$('#order-state'),bs=$('#budget-state'),mark=(el,errs,ok)=>{if(!el)return;el.closest('.doc-card').classList.toggle('ready',!errs.length);el.innerHTML=errs.length?'Бракує: '+esc(errs.join(', ')):icon('check')+ok};mark(os,oe,'Готовий до друку');mark(bs,oe.length?oe:be,money(costTotal(state.event.items))+' ₴');state.event.items.forEach((r,i)=>{const el=document.querySelector(`[data-line-total="${i}"]`);if(el)el.textContent=money(r.qty*r.price)+' ₴'});const errs=eventErrors(true),st=$('#preview-status');if(st){st.className='hero-status '+(errs.length?'warn':'ok');st.innerHTML=errs.length?'Заповніть: '+esc(errs.join(', ')):icon('check')+'Наказ і кошторис готові до друку'}const od=$('#order-date'),o=eventDates(state.event).orderDate;if(od)od.textContent=o?`Дата наказу й кошторису — ${date(o)}, за день до дати чеку. Ставиться автоматично.`:'Дата наказу ставиться автоматично: за день до дати чеку.'}
 if(view==='travel'){prepareMonthly();const t=state.travel,r=fuelMetrics(t),v=(x,u='')=>x===undefined||x===null||!Number.isFinite(x)?'—':num(x)+u;
  const kt=$('#km-total');if(kt)kt.innerHTML=`${r.error||r.total===undefined?'—':num(r.total)} <small>км</small>`;
  const st=$('#fuel-status');if(st){const over=!r.error&&r.actualRate>Number(t.rate)+1e-9;st.className='hero-status '+(r.error||over?'warn':'ok');st.innerHTML=r.error?esc(!Number(t.refill)&&Number(t.startFuel)<=Number(t.endTarget)?'Введіть, скільки пального залили':r.error):over?'Фактична витрата більша за норму. Приберіть від’ємну поправку в «Початкових даних».':`${icon('check')}Фактично ${fraction(r.actualRate,Number(t.liters))} · норма ${fraction(Number(t.rate),r.normFuel)}`}
  const range=$('#tank-range');if(range){const max=tankMax();if(+range.max!==max)range.max=max;if(document.activeElement!==range)range.value=t.endTarget;range.style.setProperty('--p',Math.min(100,Number(t.endTarget)/max*100)+'%');const zone=document.querySelector('.tank-zone');if(zone){zone.style.left=Math.min(100,15/max*100)+'%';zone.style.width=Math.max(0,Math.min(100,25/max*100)-Math.min(100,15/max*100))+'%'}}
  const ri=$('#refill-input');if(ri)ri.style.width=(ri.value||'0').length+.6+'ch';const tv=$('#tank-value');if(tv)tv.textContent=num(t.endTarget)+' л';
  const th=$('#tank-hint');if(th){const e=Number(t.endTarget);th.className='hint center'+(e<8||e>32?' warn-text':'');th.textContent=r.error?'':e<8?'Майже порожній бак. Краще тримати ближче до середини, 15–25 л.':e>32?'Бак майже повний. Краще тримати ближче до середини, 15–25 л.':`Добре, бак біля середини. Кожен літр ≈ ${num(round(100/Number(t.rate||1),1))} км пробігу.`}
  [['#j-fuel-start',v(Number(t.startFuel),' л')],['#j-fuel-end',v(Number(t.endTarget),' л')],['#j-odo-start',v(Number(t.odometer))],['#j-odo-end',r.error?'—':v(r.endOdo)]].forEach(([q,x])=>{const el=$(q);if(el)el.textContent=x});const sh=$('#sheet');if(sh){const d=s=>s?new Date(s+'T12:00:00').toLocaleDateString('uk-UA'):'—';sh.innerHTML=[['Період',`${d(t.from)} – ${d(t.to)}`],['Автомобіль',esc([t.car,t.plate].filter(Boolean).join(' · ')||'—')],['Водій',esc(t.driver||'—')],['Залишок при виїзді',v(Number(t.startFuel),' л')],['Видано (заправлено)',v(Number(t.refill),' л')],['Залишок при поверненні',r.error?'—':v(r.endFuel,' л')],['Одометр при виїзді',v(Number(t.odometer))],['Одометр при поверненні',r.error?'—':v(r.endOdo)],['Пробіг',r.error?'—':v(r.total,' км')],['Витрата за нормою',r.error?'—':fraction(Number(t.rate),r.normFuel)],['Витрата фактична',r.error?'—':fraction(r.actualRate,Number(t.liters))],...(r.rows||[]).filter(x=>x.route.trim()).map((x,i)=>[`Поїздка ${i+1}`,`${esc(x.route)} · ${num(x.km)} км`])].map(([a,b])=>`<div><span>${a}</span><b>${b}</b></div>`).join('')}
  const rc=$('#real-comparison');if(rc)rc.innerHTML=r.realDifference===null||r.error?'<p class="hint">Лише для порівняння, у бланк не потрапляє.</p>':`<p class="hint">${Math.abs(r.realPercent)<=3?'Сходиться':'Розходження'}: за приладом ${r.realDifference>0?'на ':'на '}${num(Math.abs(r.realDifference))} км ${r.realDifference>=0?'більше':'менше'} за розрахунок (${num(Math.abs(r.realPercent))}%). Лише для інформації, у бланк не потрапляє.</p>`;
  const last=$('[data-last-km]');if(last)last.value=r.rows?.at(-1)?.km??0}
}
function eventErrors(budget){const e=state.event;let errors=[];if(!e.venue.trim())errors.push('назву закладу');if(!validDate(e.date))errors.push('дату круглого столу');if(!eventDates(e).orderDate)errors.push('дату чеку');if(!e.person.trim())errors.push('відповідальну особу');if(!e.products.length)errors.push('хоча б один препарат');if(budget&&(!e.items.length||e.items.some(r=>!r.name.trim()||!(Number(r.qty)>0)||Number(r.price)<0||!Number.isFinite(Number(r.price)))))errors.push('коректні позиції кошторису');return errors}
function travelErrors(){const t=state.travel,r=travelCalc(t);if(r.error)return r.error;if([t.odometer,t.startFuel,t.endTarget].some(n=>!Number.isFinite(Number(n))||Number(n)<0))return 'Залишок, заправка й одометр мають бути невід’ємними.';if(!t.driver.trim()||!t.car.trim()||!t.plate.trim())return 'Заповніть водія, автомобіль і державний номер.';if(!t.from||!t.to||t.to<t.from)return 'Перевірте початок і кінець періоду.';if(t.rows.some(r=>r.route.trim()&&(!r.date||r.date<t.from||r.date>t.to)))return 'Дати поїздок мають бути в межах місяця.';return ''}
function documentHtml(type){const e=state.event,p=state.profile,d=eventDates(e).orderDate,val=s=>esc(s||'________________');if(type==='order')return `<article class="paper order"><h1>Н А К А З №${val(e.number)}</h1><div class="order-date"><span>м. ${val(e.city)}</span><span>${longDate(d)}</span></div><div class="order-subject">«Про організацію круглого столу<br>у ${val(e.venue)}»</div><p class="command">Наказую:</p><p>${val(e.person)} провести круглий стіл ${date(e.date)} року у ${val(e.venue)} по препаратах: ${val(e.products.join(', '))}</p><p class="order-point">1. &nbsp; Скласти кошторис.</p><p>Підстава: Розпорядження керівника.</p><div class="order-sign"><span>${val(p.position)}<br>${val(p.company)}</span><span>${val(p.head)}</span></div></article>`;if(type==='budget'){const total=money(costTotal(e.items));return `<article class="paper budget"><h1>К О Ш Т О Р И С</h1><p class="budget-subject">Про організацію круглого столу у ${val(e.venue)}</p><div class="amount-line">${total}</div><div class="amount-hint">( сума витрат подано в гривнях)</div><table><thead><tr><th>№</th><th>Опис затрат</th><th>Сума</th></tr></thead><tbody>${e.items.map((r,i)=>`<tr><td>${i+1}</td><td>${val(r.name)}</td><td class="amount">${money(r.qty*r.price)}</td></tr>`).join('')}<tr><td>&nbsp;</td><td></td><td></td></tr><tr><td>&nbsp;</td><td></td><td></td></tr><tr><td></td><td>Всього</td><td class="amount">${total}</td></tr></tbody></table><p class="budget-date">дата: ${date(d)}</p><p class="budget-sign">${val(p.position)}:__________________ ${val(p.budgetHead)}</p></article>`}const t=state.travel,r=travelCalc(t);return travelTemplate(t,r)}
function fitPreview(){const box=$('#full-preview');box.querySelectorAll('.preview-scale').forEach(el=>{const doc=el.firstElementChild;el.style.zoom=1;const w=doc.offsetWidth;el.style.zoom=Math.min(1,(box.clientWidth-24)/w)})}
function preview(type){docType=type;$('#dialog-print').innerHTML=type==='travel'?icon('print')+'Друк':icon('print')+'Друкувати обидва';const dlg=$('#preview-dialog');$('#preview-switch').innerHTML=type==='travel'?'':`<div class="segmented small"><button data-doc="order" class="${type==='order'?'selected':''}">Наказ</button><button data-doc="budget" class="${type==='budget'?'selected':''}">Кошторис</button></div>`;const html=documentHtml(type);$('#full-preview').innerHTML=type==='travel'?html.split(/(?=<article)/).filter(Boolean).map(a=>`<div class="preview-scale">${a}</div>`).join(''):`<div class="preview-scale">${html}</div>`;if(!dlg.open)dlg.showModal();requestAnimationFrame(fitPreview)}
window.addEventListener('resize',()=>{if($('#preview-dialog').open)fitPreview()});
function printDoc(type,both=false){if(type==='travel'){const err=travelErrors();if(err)return toast(err)}else{const errors=eventErrors(type==='budget'||both);if(errors.length)return toast('Заповніть: '+errors.join(', ')+'.')}$('#page-style').textContent=`@page { size: ${type==='travel'?'A5':'A4'} portrait; margin: 0; }`;$('#print-root').innerHTML=both?documentHtml('order')+documentHtml('budget'):documentHtml(type);document.body.classList.add('printing');window.print()}
window.addEventListener('afterprint',()=>document.body.classList.remove('printing'));
function storeReport(type){const errors=type==='event'?eventErrors(true).join(', '):travelErrors();if(errors)return toast(type==='event'?'Заповніть: '+errors:errors);const copy=structuredClone(type==='event'?state.event:state.travel);state.archive.push({id:crypto.randomUUID(),type,title:type==='event'?copy.venue:copy.driver,date:type==='event'?copy.date:copy.from,data:copy,profile:structuredClone(state.profile)});save();toast(storageOK?'Звіт збережено в архіві.':'Не вдалося зберегти. Завантажте резервну копію.');render()}
function backup(){const blob=new Blob([JSON.stringify(state,null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=`zvit-backup-${today()}.json`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
function validBackup(s){const str=x=>typeof x==='string'&&x.length<2000,arr=x=>Array.isArray(x)&&x.length<500,num=x=>Number.isFinite(Number(x))&&Number(x)>=0;const event=e=>e&&['venue','date','number','city','person'].every(k=>str(e[k]))&&(e.receiptDate===undefined||(str(e.receiptDate)&&(e.receiptDate===''||validDate(e.receiptDate))))&&arr(e.products)&&e.products.every(str)&&arr(e.items)&&e.items.every(r=>str(r.name)&&num(r.qty)&&num(r.price));const travel=t=>t&&['driver','car','plate','from','to'].every(k=>str(t[k]))&&['liters','rate','startFuel','refill','odometer'].every(k=>num(t[k]))&&(t.endTarget===undefined||num(t.endTarget))&&(t.adjustmentKm===undefined||Number.isFinite(Number(t.adjustmentKm)))&&arr(t.rows)&&t.rows.length>0&&t.rows.every(r=>str(r.date)&&str(r.route)&&num(r.km));const profile=p=>p&&['company','head','budgetHead','position'].every(k=>str(p[k]));return s?.version===1&&validDirectory(s.clinics,'clinics')&&validDirectory(s.representatives,'representatives')&&event(s.event)&&travel(s.travel)&&profile(s.profile)&&arr(s.products)&&s.products.every(str)&&arr(s.archive)&&s.archive.every(r=>str(r.id)&&/^[a-zA-Z0-9-]+$/.test(r.id)&&str(r.title)&&str(r.date)&&profile(r.profile)&&(r.type==='event'?event(r.data):r.type==='travel'&&travel(r.data)))}
