document.addEventListener('input',ev=>{const el=ev.target,ds=el.dataset;if(ds.directory){contactDrafts[ds.directory][ds.contactField]=el.value;return}if(ds.realOdo!==undefined){state.travel.realKm=el.value===''?'':round(Number(el.value)-Number(state.travel.odometer));save();updateDerived();return}if(el.id==='archive-search'){$('#archive-list').innerHTML=archiveList(el.value);return}if(ds.key){const [obj,key]=ds.key.split('.');state[obj][key]=key==='realKm'&&el.value===''?'':el.type==='number'||el.type==='range'?Number(el.value):el.value;if(obj==='travel'&&key==='adjustmentKm'&&state.travel.adjustmentKm<0){state.travel.adjustmentKm=0;el.value=0;toast('Фактична витрата не може бути більшою за норму, тому від’ємний пробіг не дозволено.')}if(obj==='travel')prepareMonthly();save();updateDerived()}if(ds.item!==undefined){state.event.items[+ds.item][ds.prop]=ds.prop==='name'?el.value:Number(el.value);save();updateDerived()}if(ds.trip!==undefined&&!el.readOnly){state.travel.rows[+ds.trip][ds.prop]=ds.prop==='km'?Number(el.value):el.value;save();updateDerived()}});
document.addEventListener('change',async ev=>{if(ev.target.hasAttribute('data-fuel-month')){const bounds=monthBounds(ev.target.value);if(!bounds)return toast('Виберіть коректний місяць.');Object.assign(state.travel,bounds);state.travel.rows.forEach(row=>row.date=bounds.from);state.travel.refill=0;state.travel.realKm='';state.travel.adjustmentKm=0;delete state.travel.autoBasisMonth;await previousFuel();save();render();return;}if(ev.target.dataset.key==='travel.car'||ev.target.dataset.key==='travel.plate'){await previousFuel();return;}const picker=ev.target.dataset.contactPicker;if(picker){const target=ev.target.dataset.target||'event',val=ev.target.value;ev.target.value='';if(!val)return;if(val==='__save')return rememberContact(picker);if(val==='__open'){contactKind=picker;contactForm[picker]=true;return go('contacts')}if(target==='preset'){const row=state.representatives.find(r=>r.id===val);if(row)Object.assign(state.preset,{representativeId:val,person:row.person})}else applyContact(state,picker,val,target);state.event.city=CITY;save();render();return}if(ev.target.id!=='restore-file')return;try{const f=ev.target.files[0];if(!f)return;if(f.size>5000000)throw Error('Файл завеликий.');const incoming=JSON.parse(await f.text());if(!validBackup(incoming))throw Error('Невірний формат резервної копії.');if(confirm('Замінити всі поточні дані даними з резервної копії?')){state=migrateDirectories(incoming);state.travel.endTarget??=state.travel.startFuel;state.travel.adjustmentKm??=0;save();render();toast('Дані відновлено.')}}catch(e){toast('Не вдалося відновити: '+e.message)}});
$('#close-preview').onclick=()=>$('#preview-dialog').close();$('#dialog-print').onclick=()=>docType==='travel'?printDoc('travel'):eventDone();
window.addEventListener('beforeinstallprompt',e=>{e.preventDefault();deferredInstall=e});if('serviceWorker'in navigator)navigator.serviceWorker.register('./sw.js').catch(()=>{});
{const q=new URLSearchParams(location.search).get('view'),hs=history.state;if(!q&&hs?.view&&views[hs.view]){view=hs.view;if(view==='travel')docType='travel'}else if(q&&views[q]&&parentOf[q]&&!parentOf[parentOf[q]]){history.replaceState({view:parentOf[q]},'','/');view=q;if(q==='travel')docType='travel';history.pushState({view,pushed:true},'','/')}else{if(q&&views[q]&&!parentOf[q])view=q;history.replaceState({view},'','/')}}render();if(session.offline)document.body.classList.add('offline');if(navigator.onLine&&'serviceWorker'in navigator)navigator.serviceWorker.ready.then(r=>r.active?.postMessage('warm')).catch(()=>{});if(!storageOK)toast('Локальне збереження недоступне. Робіть резервні копії.');
